#pragma once

// Identity of the desktop application (architecture-m3.md 15.12): its version and source digest,
// those of the library, the Qt versions and the build. The text is shown by the About box and
// by `sinus-desktop --version`, and heads the recordings and the log.

#include <string>
#include <string_view>

namespace sinus::desktop::core {

// Version of the milestone register and SHA-256 of an item's own code.
struct ItemIdentity {
  const char* version;
  const char* source_sha256;
};

// The version and digest of desktop/src; the definition is generated by CMake at build time.
[[nodiscard]] ItemIdentity desktop_identity() noexcept;

// What the build states about itself, from CMake.
struct BuildInfo {
  const char* qt_build_version;  // the Qt the application was built with
  const char* compiler;          // "<compiler id> <version>"
  const char* build_type;        // CMake build type
  bool other_qt_allowed;         // SINUS_DESKTOP_ALLOW_OTHER_QT was ON
};

[[nodiscard]] BuildInfo build_info() noexcept;

struct IdentityInputs {
  ItemIdentity desktop;
  ItemIdentity library;
  BuildInfo build;
  std::string_view qt_runtime_version;  // the Qt loaded at run time (qVersion())
};

// The identity text, one statement per line, each line ending with a new line.
[[nodiscard]] std::string identity_text(const IdentityInputs& inputs);

// The identity text of this build, with the library's identity and the given Qt run-time version.
[[nodiscard]] std::string current_identity_text(std::string_view qt_runtime_version);

}  // namespace sinus::desktop::core
